// Keyboard input: held state + edge-triggered presses consumed once per frame.
window.Input = (() => {
  const KEYMAP = {
    ArrowUp: 'up', KeyW: 'up',
    ArrowDown: 'down', KeyS: 'down',
    ArrowLeft: 'left', KeyA: 'left',
    ArrowRight: 'right', KeyD: 'right',
    KeyZ: 'a', Enter: 'a', Space: 'a',
    KeyX: 'b', Escape: 'b',
    KeyM: 'menu', Backquote: 'menu',
  };
  const held = {};
  const pressed = {};

  addEventListener('keydown', (e) => {
    const k = KEYMAP[e.code];
    if (!k) return;
    e.preventDefault();
    if (!held[k]) pressed[k] = true;
    held[k] = true;
    Audio2.unlock();
  });
  addEventListener('keyup', (e) => {
    const k = KEYMAP[e.code];
    if (k) held[k] = false;
  });

  return {
    held: (k) => !!held[k],
    // Consume a press (edge). Returns true once per physical key press.
    press: (k) => { const v = !!pressed[k]; pressed[k] = false; return v; },
    endFrame: () => { for (const k in pressed) pressed[k] = false; },
    dirHeld: () => held.up ? 'up' : held.down ? 'down' : held.left ? 'left' : held.right ? 'right' : null,
  };
})();
